!function(e){function r(r){for(var t,n,o=r[0],m=r[1],c=r[2],s=0,g=[];s<o.length;s++)n=o[s],Object.prototype.hasOwnProperty.call(a,n)&&a[n]&&g.push(a[n][0]),a[n]=0;for(t in m)Object.prototype.hasOwnProperty.call(m,t)&&(e[t]=m[t]);for(d&&d(r);g.length;)g.shift()();return p.push.apply(p,c||[]),i()}function i(){for(var e,r=0;r<p.length;r++){for(var i,n=p[r],o=!0,m=1;m<n.length;m++)i=n[m],0!==a[i]&&(o=!1);o&&(p.splice(r--,1),e=t(t.s=n[0]))}return e}function t(r){if(n[r])return n[r].exports;var i=n[r]={i:r,l:!1,exports:{}};return e[r].call(i.exports,i,i.exports,t),i.l=!0,i.exports}var n={},a={55:0},p=[];t.m=e,t.c=n,t.d=function(e,r,i){t.o(e,r)||Object.defineProperty(e,r,{enumerable:!0,get:i})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,r){if(1&r&&(e=t(e)),8&r)return e;if(4&r&&"object"==typeof e&&e&&e.__esModule)return e;var i=Object.create(null);if(t.r(i),Object.defineProperty(i,"default",{enumerable:!0,value:e}),2&r&&"string"!=typeof e)for(var n in e)t.d(i,n,function(r){return e[r]}.bind(null,n));return i},t.n=function(e){var r=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(r,"a",r),r},t.o=function(e,r){return Object.prototype.hasOwnProperty.call(e,r)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=r,o=o.slice();for(var c=0;c<o.length;c++)r(o[c]);var d=m;p.push([228,0]),i()}({228:function(e,r,i){"use strict";i.r(r);var t=i(0);Object(t.a)("de","army",i(229),i(1))},229:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"轻武器","link":"de_army#de_army_iw"}],"model":"“坦克杀手”反坦克火箭筒","description":"<p>“坦克杀手”反坦克火箭筒是德军用从苏军手中缴获的美军“巴祖卡”反坦克火箭筒改进制作的一种可重复使用的反坦克武器。但比“巴祖卡”有更远的射程和更强的穿甲能力，能有效地击穿苏军T-34坦克的装甲。早期的“坦克杀手”反坦克火箭筒为RPzB 43型，在1943年开始装备德军；此型火箭筒由于发射时火箭弹会产生近2米的尾焰，对射手有较大危害，后经改进，加装了防护盾，型号改为RPzB 54型。</p><p>“坦克杀手”反坦克火箭筒装备德军后，德国陆军一部分原装备50mm Pak38型和75mm Pak42型反坦克炮的团属反坦克炮兵连直接改为全部装备“坦克杀手”反坦克火箭筒，每连下属三个反坦克火箭筒排，一共配备54具“坦克杀手”反坦克火箭筒（有些连会保留部分75mm Pak42型反坦克炮），用密集的反坦克火箭弹来对抗苏军的T-34坦克集群进攻。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_iwRPzB_11.jpg","description":"<h6>RPzB 54型“坦克杀手”反坦克火箭筒</h6><p></p><p>技术数据：</p><p>口径：88毫米，长度：1640毫米，重量：11公斤；</p><p>弹药装量：2.4公斤，火箭弹出膛初速：110米/秒；</p><p>有效射程：150米（采用新型火箭弹，射程可达180米）；</p><p>破甲厚度：垂直200毫米；30度倾角160毫米。</p>","caption":""}],"part2title":"战场上的“坦克杀手”反坦克火箭筒","part2description":"","part2content":[{"image":"imgs/de/army/de_army_iwRPzB_21.jpg","description":"绘图：1944年，西线战场法国诺曼底地区，一名背着RPzB 54型“坦克杀手”反坦克火箭筒的德军第21掷弹兵装甲师的反坦克炮连士兵正在一路标旁问路。","caption":""},{"image":"imgs/de/army/de_army_iwRPzB_22.jpg","description":"战壕中，两名德军伞兵准备用RPzB 54型“坦克杀手”反坦克火箭筒发射火箭弹射击敌方坦克，其中一名士兵负责装弹，另一名士兵手握板机正在瞄准。","caption":""},{"image":"imgs/de/army/de_army_iwRPzB_23.jpg","description":"一个配备RPzB 54型“坦克杀手”反坦克火箭筒的德军反坦克小组两名士兵埋伏在草丛中，准备伏击苏军坦克。","caption":""},{"image":"imgs/de/army/de_army_iwRPzB_24.jpg","description":"1944年西线战场，一名德军士兵用88毫米RPzB 54型“坦克杀手”反坦克火箭筒在树篱中等候盟军坦克。德军反坦克连队通常会将反坦克火箭筒射手分散隐蔽，以突然袭击的手段攻击敌军坦克。","caption":""},{"image":"imgs/de/army/de_army_iwRPzB_25.jpg","description":"1943年，东线苏联战场，两名德军士兵分别拿着“坦克杀手”反坦克火箭筒和“铁拳”反坦克榴弹发射器穿行在树丛中，准备猎杀苏军坦克。","caption":""},{"image":"imgs/de/army/de_army_iwRPzB_26.jpg","description":"东线苏联战场，两名德军士兵正在战壕中抵御苏军进攻，一名士兵拿着步枪，另一名士兵拿着“坦克杀手”反坦克火箭筒。","caption":""},{"image":"imgs/de/army/de_army_iwRPzB_27.jpg","description":"1944年10月，德国战场，一名在田野中作了伪装的德国“人民冲锋队”的成员士兵拿着“坦克杀手”反坦克火箭筒正在等待苏军坦克的进攻。","caption":""},{"image":"imgs/de/army/de_army_iwRPzB_28.jpg","description":"1944年西线战场法国诺曼第地区，一名的手持RPzB 54型“坦克杀手”反坦克火箭筒的德军士兵隐藏在树丛中，准备攻击进攻的盟军坦克。注：在1943年末，便携式“坦克杀手”反坦克火箭筒已广泛地装备给德军的团属反坦克连，由此大大提高了德国步兵对敌军坦克的攻击能力，当然，最终这也无法抵挡二战后期苏军与盟军坦克集群的猛烈进攻。","caption":""},{"image":"imgs/de/army/de_army_iwRPzB_29.jpg","description":"在1944年夏末，西线法国战场，手持“坦克杀手”反坦克火箭筒和“铁拳”反坦克榴弹发射器的德军反坦克排士兵在一辆被击毁的英军M4A4型坦克旁经过，边走边警惕地注视着四周的情况。","caption":""},{"image":"imgs/de/army/de_army_iwRPzB_30.jpg","description":"绘图：二战战场上，一个装备“坦克杀手”反坦克火箭筒的德军反坦克小组正在准备迎击进攻的坦克。“坦克杀手”反坦克火箭筒一般都由二人操作，一人为弹药手，负责携带弹药和火箭弹的装填，另一人为射手，负责瞄准和射击。","caption":""},{"image":"imgs/de/army/de_army_iwRPzB_31.jpg","description":"绘图：一个携带“坦克杀手”反坦克火箭筒与弹药的德军士兵。在人员不足的情况下，“坦克杀手”反坦克火箭筒的装弹和射击也会由一人独自承担，但在战场上一人操作相对两人小组的反应会慢很多。","caption":""},{"image":"imgs/de/army/de_army_iwRPzB_32.jpg","description":"绘图：1945年4月，德国鲁尔区，携带“坦克杀手”反坦克火箭筒与“铁拳”反坦克榴弹发射器的德国“人民冲锋队”成员。","caption":""}]}')}});